import os
import torch


class Config:
    """
    Configuration for Lightweight-Attention Residual-Fusion Network (LARF-Net).
    """

    # ==========================
    # General Settings
    # ==========================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Adjust based on available vCPUs (12 available)

    # ==========================
    # Data Paths
    # ==========================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Caching
    # Directory to store processed Tri-Slab numpy arrays
    CACHE_DIR = "./working/idea_35/"
    LOAD_CACHED_DATA = True

    # ==========================
    # Image Processing (Tri-Slab)
    # ==========================
    IMG_SIZE = 224  # Native resolution to avoid upscaling artifacts
    IN_CHANNELS = 3  # RGB (MIP mapped to channels or repeated)
    SLAB_COUNT = 3  # 3 slabs per view
    SLAB_OVERLAP = 0.15  # 15% overlap between slabs

    # ==========================
    # Model Architecture (LARF-Net)
    # ==========================
    BACKBONE_NAME = "efficientnet_b0"
    BACKBONE_PRETRAINED = True

    # Native dimensionality of EfficientNet-B0 final features (before classifier)
    # Kept high to preserve texture signals
    BACKBONE_DIM = 1280

    # Tabular Data Dimensions
    # Age(1) + Percent(1) + Sex(2 one-hot) + Smoking(3 one-hot) = 7
    TABULAR_INPUT_DIM = 7

    # Fusion / Attention
    # The tabular features are projected up to this dim to match visual features
    FUSION_DIM = 1280

    # Lightweight Attention Settings
    ATTN_HEADS = 8
    ATTN_LAYERS = 1
    USE_FFN = False  # Critical: Remove FFN to reduce overfitting
    DROPOUT = 0.1

    # ==========================
    # Training Hyperparameters
    # ==========================
    BATCH_SIZE = 16
    EPOCHS = 50
    LR = 1e-4
    WEIGHT_DECAY = 1e-2

    # Scheduler
    SCHEDULER = "CosineAnnealingLR"
    T_MAX = EPOCHS
    ETA_MIN = 1e-6

    # Early Stopping
    PATIENCE = 8  # Strict patience

    # ==========================
    # Metric / Loss
    # ==========================
    # Thresholds for the modified Laplace Log Likelihood
    MAX_ERROR_CLIP = 1000
    MIN_CONFIDENCE_CLIP = 70

    # ==========================
    # Debugging
    # ==========================
    DEBUG = False  # Set to True to run on a small subset
    DEBUG_SUBSET_SIZE = 50

    @classmethod
    def print_config(cls):
        print("\n" + "=" * 40)
        print(f"CONFIGURATION: {cls.__name__}")
        print("=" * 40)
        for k, v in cls.__dict__.items():
            if not k.startswith("__") and not callable(v):
                print(f"{k:<25}: {v}")
        print("=" * 40 + "\n")
